// size = bredd; hojden = size * 100/125 (liggande). Platta = blek lagfarg, ram = full lagfarg.
export function logoSVG(areaId, size = 96) {
  const e = EMBLEM[areaId], c = TEAM_LOGOS[areaId];
  if (!e) return '';
  const h = Math.round(size * 100 / 125);
  return `<svg width="${size}" height="${h}" viewBox="0 0 125 100" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="${c.djur}" style="display:inline-block;vertical-align:middle;flex:none">`
    + `<rect x="3" y="3" width="119" height="94" rx="16" fill="${c.panel}"/>`
    + `<svg x="8" y="7" width="109" height="86" viewBox="${e.vb}" preserveAspectRatio="xMidYMid meet">${e.svg}</svg>`
    + `<rect x="3" y="3" width="119" height="94" rx="16" fill="none" stroke="${c.farg}" stroke-width="5"/>`
    + `</svg>`;
}
